import { fileURLToPath } from 'node:url'
import { defineConfig } from 'vitest/config'

/**
 * Unit tests for the renderer (#1145). jsdom gives TipTap the DOM it needs to
 * build a headless editor; IndexedDB is mocked per test file. Run with
 * `npm run test:unit`.
 */
export default defineConfig({
  test: {
    environment: 'jsdom',
    include: ['src/**/*.test.ts'],
    setupFiles: ['src/renderer/test/setup.ts'],
    css: false,
    // `src/main/env.ts` is generated by the build and CI runs these tests first;
    // main-process code under test imports a committed default instead (#1223).
    alias: [{ find: /^(\.\.?\/)+env$/, replacement: fileURLToPath(new URL('./src/main/env.vitest.ts', import.meta.url)) }]
  }
})
